// Bundles the storefront themes into generated modules, so the Convex backend can serve
// them as zips (convex/storeThemeHttp.ts):
//   shopify-theme/       → convex/lib/themeFiles.generated.ts  (our AdSpy Storefront theme)
//   shopify-theme-dawn/  → convex/lib/dawnFiles.generated.ts   (Shopify's Dawn + our adspy-* sections)
// Run after changing anything in either folder:  node scripts/build-theme.mjs
// convex/storeTheme.test.ts and convex/dawnTheme.test.ts fail while a generated file is out of date.

import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const repo = join(fileURLToPath(import.meta.url), "..", "..");
const themeDir = join(repo, "shopify-theme");
const dawnDir = join(repo, "shopify-theme-dawn");

const THEME_FOLDERS = new Set(["assets", "config", "layout", "locales", "sections", "snippets", "templates", "blocks"]);
const LANDING_PATHS = ["layout/adspy-landing.liquid", "templates/page.adspy-landing.liquid", "sections/adspy-landing-home.liquid"];
const BINARY = /\.(gif|png|jpe?g|webp|ico|woff2?|ttf|otf|eot)$/i;

/** Text files of a theme folder ({ "layout/theme.liquid": "…" }), and binary ones as base64. Only Shopify's theme folders. */
export function readThemeFolder(dir) {
  const files = {};
  const binary = {};
  const walk = (d) => {
    for (const name of readdirSync(d).sort()) {
      const p = join(d, name);
      const rel = relative(dir, p).split(sep).join("/");
      if (statSync(p).isDirectory()) {
        if (d !== dir || THEME_FOLDERS.has(name)) walk(p);
      } else if (d !== dir) {
        if (BINARY.test(name)) binary[rel] = readFileSync(p).toString("base64");
        else files[rel] = readFileSync(p, "utf8").replace(/\r\n/g, "\n");
      }
    }
  };
  walk(dir);
  return { files, binary };
}

export function readTheme(dir = themeDir) {
  return readThemeFolder(dir).files;
}

export function readDawn(dir = dawnDir) {
  return readThemeFolder(dir);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const files = readTheme();
  writeFileSync(
    join(repo, "convex", "lib", "themeFiles.generated.ts"),
    "// Generated by scripts/build-theme.mjs from shopify-theme/. Don't edit by hand.\n" +
      "/* eslint-disable */\n" +
      `export const THEME_FILES: Record<string, string> = ${JSON.stringify(files, null, 1)};\n`,
  );
  console.log(`${Object.keys(files).length} theme files bundled`);

  const dawn = readDawn();
  writeFileSync(
    join(repo, "convex", "lib", "dawnFiles.generated.ts"),
    "// Generated by scripts/build-theme.mjs from shopify-theme-dawn/ (Shopify Dawn, license in\n" +
      "// shopify-theme-dawn/LICENSE.md and snippets/dawn-license.liquid). Don't edit by hand.\n" +
      "/* eslint-disable */\n" +
      `export const DAWN_FILES: Record<string, string> = ${JSON.stringify(dawn.files)};\n` +
      "/** Binary files, base64. */\n" +
      `export const DAWN_BINARY: Record<string, string> = ${JSON.stringify(dawn.binary)};\n`,
  );
  console.log(`${Object.keys(dawn.files).length + Object.keys(dawn.binary).length} Dawn files bundled`);

  // Screenshot to page → Publish to Shopify adds these to a store's live theme (convex/lib/landingShopify.ts).
  const landing = Object.fromEntries(LANDING_PATHS.map((p) => [p, files[p]]));
  writeFileSync(
    join(repo, "convex", "lib", "landingFiles.generated.ts"),
    "// Generated by scripts/build-theme.mjs from shopify-theme/. Don't edit by hand.\n" +
      "/* eslint-disable */\n" +
      `export const LANDING_FILES: Record<string, string> = ${JSON.stringify(landing, null, 1)};\n`,
  );
}
